import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();

        n = n - 1 + (1 << h);
        int res = h;

        for (int i = 1; i <= h; i++) {
            int a = n & (1 << i);
            int b = n & (1 << (i - 1));
            if (!(((a == 0) ? 0 : 1) ^ ((b == 0) ? 0 : 1) != 0)) {
                res += (1 << i) - 1;
            }
        }
        System.out.println(res);
        sc.close();
    }
}
